/**
 * Native Haven v2 design tokens — the single source of truth.
 *
 * Every consumer derives from this module instead of copying values:
 *   - CSS custom properties (`haven.css`) are generated by `renderHavenCss()`
 *     (`pnpm tokens:build`; a unit test fails when the file is stale),
 *   - charts and canvas drawing read the typed values directly,
 *   - the Expo app and the Pencil file mirror the values by script, never by hand.
 *
 * Spec: docs/design-system/foundations.md. Names are roles, not hues: a
 * component asks for `secondary`, never for "gray 600".
 */

export type ThemeMode = 'light' | 'dark';
export interface ModeValue {
  light: string;
  dark: string;
}

/** Semantic colors. The keys become `--gh-<kebab-key>`. */
export const color = {
  // Surfaces, back to front.
  canvas: { light: '#FFFFFF', dark: '#111113' }, // the work area
  chrome: { light: '#F2F2F7', dark: '#1C1C1E' }, // module column, grouped backgrounds
  rail: { light: '#EDEDF2', dark: '#161618' }, // global rail
  surface: { light: '#FFFFFF', dark: '#242426' }, // controls and cards on canvas or chrome
  raised: { light: '#FFFFFF', dark: '#2A2A2D' }, // menus, popovers, dialogs, drawers, sheets
  fill: { light: '#F0F0F4', dark: '#2A2A2D' }, // neutral fills: segmented track, code, skeleton
  hover: { light: '#E8E8ED', dark: '#303033' },
  pressed: { light: '#DEDEE4', dark: '#3A3A3E' },
  selection: { light: '#E2ECE6', dark: '#263A30' }, // current row / nav item (brand-derived)
  scrim: { light: 'rgba(17, 17, 19, 0.32)', dark: 'rgba(0, 0, 0, 0.6)' },

  // Lines.
  line: { light: '#E4E4E9', dark: '#333336' }, // decorative dividers; no contrast requirement
  controlLine: { light: '#86868B', dark: '#707078' }, // input, checkbox and switch boundaries (≥ 3:1)

  // Text and icons.
  text: { light: '#1C1C1E', dark: '#F5F5F7' },
  secondary: { light: '#636366', dark: '#AEAEB2' }, // supporting text (≥ 4.5:1)
  tertiary: { light: '#86868B', dark: '#7C7C82' }, // placeholders, the "?" hint, non-essential meta (≥ 3:1)

  // Brand accent. A workspace brand color regenerates this group only.
  accent: { light: '#235D4D', dark: '#B1D2BF' }, // primary action fill, selected indicator, focus
  accentHover: { light: '#1C4D40', dark: '#C4DECE' },
  accentPressed: { light: '#163E34', dark: '#D2E7DA' },
  accentText: { light: '#235D4D', dark: '#B1D2BF' }, // links and accent-colored text on canvas
  onAccent: { light: '#FFFFFF', dark: '#10291F' }, // text on an accent fill
  focus: { light: '#235D4D', dark: '#B1D2BF' },

  // The Greenhouse mark (packages/ui/src/assets/greenhouse-mark.svg). Fixed: a workspace brand color never changes it.
  brandMark: { light: '#235D4D', dark: '#B1D2BF' }, // the house: ≥ 3:1 on canvas, chrome and rail
  brandSeed: { light: '#B6CA68', dark: '#B6CA68' }, // the seed in the doorway: decorative; 3:1 only on dark surfaces

  // Status: foreground + soft fill pairs. Never the only signal — always with text or an icon.
  success: { light: '#1F7A4C', dark: '#6FD39C' },
  successFill: { light: '#E3F3E9', dark: '#1A3326' },
  warning: { light: '#9A5B08', dark: '#FFC46B' }, // "needs you"
  warningFill: { light: '#FFF2DE', dark: '#382B1B' },
  danger: { light: '#C23A34', dark: '#FF8A84' },
  dangerHover: { light: '#A8302B', dark: '#FFA19C' }, // one step deeper: danger text and the solid danger fill on hover
  dangerFill: { light: '#FCEBE9', dark: '#43231F' },
  dangerFillHover: { light: '#F8DAD6', dark: '#552B26' }, // one step deeper than dangerFill: the danger button on hover
  onDanger: { light: '#FFFFFF', dark: '#111113' }, // text on a solid danger fill (the final destructive confirmation)
  info: { light: '#2A64AD', dark: '#8CBBF5' },
  infoFill: { light: '#E6EEF9', dark: '#1B2A3D' },
} as const satisfies Record<string, ModeValue>;

export type ColorToken = keyof typeof color;

/**
 * Categorical palette for user-chosen colors: tags, select options, avatar tints,
 * calendar events. `fg` is text/icon on `fill`; chart series use `fg`.
 */
export const categorical = {
  gray: { fg: { light: '#5F6168', dark: '#B4B6BC' }, fill: { light: '#EEEEF1', dark: '#26272B' } },
  red: { fg: { light: '#C8302F', dark: '#FF9590' }, fill: { light: '#FDECEB', dark: '#3B1B1B' } },
  orange: { fg: { light: '#AD4600', dark: '#FFA25C' }, fill: { light: '#FEEEDF', dark: '#35210F' } },
  amber: { fg: { light: '#9C6100', dark: '#FFCB47' }, fill: { light: '#FDF3D3', dark: '#33270D' } },
  green: { fg: { light: '#1D7A4F', dark: '#5ED59A' }, fill: { light: '#E4F4EA', dark: '#16301F' } },
  teal: { fg: { light: '#00796A', dark: '#3CD3BA' }, fill: { light: '#DFF4F0', dark: '#0F2E2A' } },
  blue: { fg: { light: '#1F6CC0', dark: '#7DB9FF' }, fill: { light: '#E5F0FC', dark: '#13294A' } },
  purple: { fg: { light: '#7A45AE', dark: '#C9A2F5' }, fill: { light: '#F2EBFB', dark: '#2C1F3D' } },
  pink: { fg: { light: '#B42F7E', dark: '#FF8FCB' }, fill: { light: '#FCEAF4', dark: '#3A1B30' } },
} as const satisfies Record<string, { fg: ModeValue; fill: ModeValue }>;

export type CategoricalColor = keyof typeof categorical;

/** Chart series order: brand first, then hues far apart from their neighbours. */
export const chartSeries = ['accent', 'blue', 'orange', 'purple', 'teal', 'pink', 'amber', 'red'] as const;

export const font = {
  sans: "'Nunito', -apple-system, BlinkMacSystemFont, 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', 'Noto Sans SC', 'Noto Sans CJK SC', sans-serif",
  mono: "'SF Mono', ui-monospace, 'JetBrains Mono', Menlo, Consolas, 'Liberation Mono', monospace",
} as const;

export interface TypeStyle {
  size: number;
  line: number;
  weight: 400 | 500 | 600 | 700;
  family?: keyof typeof font;
}

/**
 * The whole type scale. Nothing renders below 12px; 16px is the reading size
 * (messages, documents) and the minimum for touch-device inputs.
 */
export const type = {
  caption: { size: 12, line: 16, weight: 400 }, // timestamps, badges, table footers
  label: { size: 13, line: 18, weight: 500 }, // field labels, column headers, segmented controls
  bodySm: { size: 13, line: 20, weight: 400 }, // dense lists and table cells
  body: { size: 14, line: 22, weight: 400 }, // default UI text, navigation rows
  bodyLg: { size: 16, line: 26, weight: 400 }, // reading: messages, documents, mobile body
  titleSm: { size: 15, line: 22, weight: 600 }, // section and card titles
  title: { size: 18, line: 26, weight: 600 }, // drawer, dialog and module titles
  titleLg: { size: 22, line: 30, weight: 600 }, // page titles
  display: { size: 28, line: 36, weight: 700 }, // document titles, the greeting
  code: { size: 13, line: 20, weight: 400, family: 'mono' },
} as const satisfies Record<string, TypeStyle>;

export type TypeToken = keyof typeof type;

/** 4px grid. Keys are the multiplier; `0.5` exists only for hairline nudges. */
export const space = {
  '0': 0,
  '0.5': 2,
  '1': 4,
  '2': 8,
  '3': 12,
  '4': 16,
  '5': 20,
  '6': 24,
  '8': 32,
  '10': 40,
  '12': 48,
  '16': 64,
} as const;

export const radius = {
  xs: 4, // checkbox
  sm: 6, // badge, tag, kbd
  md: 8, // button, input, menu item, row highlight
  lg: 12, // card, popover, menu, toast
  xl: 16, // dialog, large card
  '2xl': 20, // composer
  sheet: 24, // mobile bottom sheet top corners
  full: 9999,
} as const;

export const shadow = {
  /** Small raised items inside a surface: the selected segment, a tooltip. */
  '1': {
    light: '0 1px 2px rgba(17, 17, 19, 0.06), 0 4px 12px rgba(17, 17, 19, 0.08)',
    dark: '0 1px 2px rgba(0, 0, 0, 0.4), 0 6px 16px rgba(0, 0, 0, 0.45)',
  },
  /** Floating layers: menus, popovers, dialogs, drawers, sheets, toasts. */
  '2': {
    light: '0 2px 8px rgba(17, 17, 19, 0.06), 0 12px 32px rgba(17, 17, 19, 0.12)',
    dark: '0 2px 8px rgba(0, 0, 0, 0.4), 0 16px 40px rgba(0, 0, 0, 0.55)',
  },
} as const satisfies Record<string, ModeValue>;

